__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"PROPHETS",{enumerable:!0,get:function(){return l}});const l=[{key:'adam',name:'Ad\u0259m',title:'\u0130lk insan v\u0259 pey\u011f\u0259mb\u0259r',story:'Allah Ad\u0259mi (\u0259) torpaqdan yaratd\u0131 v\u0259 ona ruhundan \xfcf\xfcrd\xfc. M\u0259l\u0259kl\u0259r\u0259 ona s\u0259cd\u0259 etm\u0259yi \u0259mr etdi; \u0130blisd\u0259n ba\u015fqa ham\u0131s\u0131 s\u0259cd\u0259 etdi. Ad\u0259m v\u0259 h\u0259yat yolda\u015f\u0131 H\u0259vva C\u0259nn\u0259td\u0259 ya\u015fay\u0131rd\u0131lar, lakin \u015feytan\u0131n v\u0259sv\u0259s\u0259si il\u0259 qada\u011fan olunan a\u011facdan yedil\u0259r. Pe\u015fman olub t\xf6vb\u0259 etdil\u0259r v\u0259 Allah onlar\u0131n t\xf6vb\u0259sini q\u0259bul etdi.',lesson:'X\u0259ta ed\u0259n t\xf6vb\u0259 il\u0259 Allaha d\xf6n\u0259 bil\u0259r; \u015feytan\u0131n v\u0259sv\u0259s\u0259sind\u0259n \xe7\u0259kinm\u0259k laz\u0131md\u0131r.'},{key:'nuh',name:'Nuh',title:'G\u0259minin pey\u011f\u0259mb\u0259ri',story:'Nuh (\u0259) q\xf6vm\xfcn\xfc 950 il boyu Allaha ibad\u0259t\u0259 \xe7a\u011f\u0131rd\u0131, lakin \xe7ox az adam iman g\u0259tirdi. Allah\u0131n \u0259mri il\u0259 b\xf6y\xfck bir g\u0259mi d\xfcz\u0259ltdi. Tufan g\u0259ldikd\u0259 iman g\u0259tir\u0259nl\u0259r v\u0259 heyvanlardan c\xfctl\u0259r g\u0259miy\u0259 mindi; inkar ed\u0259nl\u0259r is\u0259 suda bo\u011fuldu.',lesson:'S\u0259bir v\u0259 d\u0259v\u0259td\u0259 d\xf6z\xfcm; haqq\u0131 t\u0259bli\u011fd\u0259 \u0259zmkarl\u0131q.'},{key:'ibrahim',name:'\u0130brahim',title:'X\u0259lilullah (Allah\u0131n dostu)',story:'\u0130brahim (\u0259) b\xfctp\u0259r\u0259st q\xf6vm\xfcn\xfc t\u0259k Allaha \xe7a\u011f\u0131rd\u0131 v\u0259 b\xfctl\u0259ri s\u0131nd\u0131rd\u0131. Onu oda atd\u0131lar, lakin Allah odu onun \xfc\xe7\xfcn s\u0259rin v\u0259 salamat etdi. Sonra o\u011flu \u0130smay\u0131lla birlikd\u0259 K\u0259b\u0259ni tikdi. Yuxusunda o\u011flunu qurban etm\u0259yi g\xf6r\xfcb t\u0259slim oldu; Allah o\u011flunun yerin\u0259 bir qo\xe7 g\xf6nd\u0259rdi.',lesson:'Allaha tam t\u0259slimiyy\u0259t (t\u0259v\u0259kk\xfcl) v\u0259 t\xf6vhid u\u011frunda c\u0259sar\u0259t.'},{key:'yusuf',name:'Yusuf',title:'S\u0259bir v\u0259 ba\u011f\u0131\u015flaman\u0131n n\xfcmun\u0259si',story:'Yusuf (\u0259) qarda\u015flar\u0131 t\u0259r\u0259find\u0259n quyuya at\u0131ld\u0131 v\u0259 qul kimi sat\u0131ld\u0131. Misird\u0259 b\xf6htana g\xf6r\u0259 zindana d\xfc\u015fd\xfc, lakin yuxu yozmaq qabiliyy\u0259ti il\u0259 tan\u0131nd\u0131 v\u0259 x\u0259zin\u0259dar oldu. Q\u0131tl\u0131q zaman\u0131 qarda\u015flar\u0131 ona m\xf6htac g\u0259ldi; Yusuf onlar\u0131 tan\u0131y\u0131b ba\u011f\u0131\u015flad\u0131 v\u0259 ail\u0259si bir araya g\u0259ldi.',lesson:'\xc7\u0259tinlikd\u0259 s\u0259bir, g\xfcc \u0259ld\u0259 ed\u0259nd\u0259 is\u0259 \u0259fv v\u0259 m\u0259rh\u0259m\u0259t.'},{key:'musa',name:'Musa',title:'K\u0259limullah (Allahla dan\u0131\u015fan)',story:'Musa (\u0259) Fironun saray\u0131nda b\xf6y\xfcd\xfc, sonra Allah onu pey\u011f\u0259mb\u0259r se\xe7di. Fironu t\u0259k Allaha \xe7a\u011f\u0131rd\u0131 v\u0259 m\xf6c\xfcz\u0259l\u0259r g\xf6st\u0259rdi. \u0130srail o\u011fullar\u0131n\u0131 Misird\u0259n \xe7\u0131xard\u0131; Allah d\u0259nizi yararaq onlara yol a\xe7d\u0131, Firon is\u0259 suda bo\u011fuldu. Turi-Sinada Allahla dan\u0131\u015fd\u0131 v\u0259 T\xf6vrat nazil oldu.',lesson:'Z\xfclm\u0259 qar\u015f\u0131 durmaq v\u0259 Allah\u0131n k\xf6m\u0259yin\u0259 g\xfcv\u0259nm\u0259k.'},{key:'davud',name:'Davud',title:'Z\u0259burun sahibi',story:'Davud (\u0259) h\u0259m pey\u011f\u0259mb\u0259r, h\u0259m d\u0259 h\xf6kmdar idi. G\u0259nc ya\u015f\u0131nda n\u0259h\u0259ng Calutu (Qoliyat) m\u0259\u011flub etdi. Allah ona Z\u0259buru verdi; s\u0259si o q\u0259d\u0259r g\xf6z\u0259l idi ki, da\u011flar v\u0259 qu\u015flar onunla birlikd\u0259 Allah\u0131 t\u0259sbeh edirdi. \u018fdal\u0259tli h\xf6km verm\u0259si il\u0259 tan\u0131n\u0131rd\u0131.',lesson:'G\xfcc Allahdand\u0131r; \u0259dal\u0259t v\u0259 \u015f\xfck\xfcr \u0259sasd\u0131r.'},{key:'suleyman',name:'S\xfcleyman',title:'Hikm\u0259t v\u0259 m\xfclk\xfcn pey\u011f\u0259mb\u0259ri',story:'S\xfcleyman (\u0259) Davudun o\u011flu idi. Allah ona b\xf6y\xfck m\xfclk, k\xfcl\u0259yi v\u0259 cinl\u0259ri ram etm\u0259, heyvanlar\u0131n dilini anlama qabiliyy\u0259ti verdi. \u018fdal\u0259ti v\u0259 hikm\u0259ti il\u0259 tan\u0131nd\u0131. B\xfct\xfcn g\xfcc\xfcn\u0259 baxmayaraq t\u0259vaz\xf6kar qald\u0131 v\u0259 h\u0259r nem\u0259t \xfc\xe7\xfcn Allaha \u015f\xfck\xfcr etdi.',lesson:'Nem\u0259t v\u0259 g\xfcc imtahand\u0131r; t\u0259vaz\xf6karl\u0131q v\u0259 \u015f\xfck\xfcr laz\u0131md\u0131r.'},{key:'isa',name:'\u0130sa',title:'Ruhullah (M\u0259ry\u0259m o\u011flu)',story:'\u0130sa (\u0259) atas\u0131z, m\xf6c\xfcz\u0259vi \u015f\u0259kild\u0259 M\u0259ry\u0259md\u0259n d\xfcnyaya g\u0259ldi v\u0259 be\u015fikd\u0259 ik\u0259n dan\u0131\u015fd\u0131. Allah\u0131n izni il\u0259 x\u0259st\u0259l\u0259ri sa\u011faltd\u0131, \xf6l\xfcl\u0259ri diriltdi v\u0259 \u0130ncili g\u0259tirdi. \u0130nsanlar\u0131 t\u0259k Allaha \xe7a\u011f\u0131rd\u0131. Onu \xf6ld\xfcrm\u0259k ist\u0259dil\u0259r, lakin Allah onu \xd6z d\u0259rgah\u0131na qald\u0131rd\u0131.',lesson:'Allah\u0131n q\xfcdr\u0259ti h\u0259r \u015fey\u0259 qadirdir; t\u0259mizlik v\u0259 t\u0259vaz\xf6karl\u0131q.'},{key:'muhammad',name:'M\u0259h\u0259mm\u0259d \ufdfa',title:'Pey\u011f\u0259mb\u0259rl\u0259rin sonuncusu',story:'M\u0259h\u0259mm\u0259d (s.\u0259.s) M\u0259kk\u0259d\u0259 do\u011fuldu v\u0259 do\u011frulu\u011fu il\u0259 "\u0259l-\u018fmin" (etibarl\u0131) adland\u0131r\u0131ld\u0131. 40 ya\u015f\u0131nda ona v\u0259hy g\u0259ldi v\u0259 Quran nazil olma\u011fa ba\u015flad\u0131. \u0130nsanlar\u0131 t\xf6vhid\u0259, \u0259dal\u0259t\u0259 v\u0259 g\xf6z\u0259l \u0259xlaqa \xe7a\u011f\u0131rd\u0131. M\u0259kk\u0259d\u0259n M\u0259din\u0259y\u0259 hicr\u0259t etdi v\u0259 \u0130slam d\xfcnyaya yay\u0131ld\u0131. O, al\u0259ml\u0259r\u0259 r\u0259hm\u0259t olaraq g\xf6nd\u0259rildi.',lesson:'Do\u011fruluq, g\xf6z\u0259l \u0259xlaq v\u0259 b\xfct\xfcn b\u0259\u015f\u0259riyy\u0259t\u0259 r\u0259hm\u0259t.'}]},1190,[]);
